export const W=1000,H=900,MAX_STROKES=1200,MAX_POINTS=120000;
export function coordinate(x,y,rect){return {x:Math.max(0,Math.min(W,(x-rect.left)/rect.width*W)),y:Math.max(0,Math.min(H,(y-rect.top)/rect.height*H))}}
export function validDocument(v,ids){if(!v||v.version!==1||!ids.includes(v.pattern)||!Array.isArray(v.strokes)||v.strokes.length>MAX_STROKES)return false;let n=0;return v.strokes.every(s=>s&&['marker','crayon','soft','eraser'].includes(s.tool)&&/^#[0-9a-f]{6}$/i.test(s.color)&&[9,20,38].includes(s.size)&&Array.isArray(s.points)&&s.points.length>0&&s.points.length<15000&&(n+=s.points.length)<=MAX_POINTS&&s.points.every(p=>Number.isFinite(p.x)&&p.x>=0&&p.x<=W&&Number.isFinite(p.y)&&p.y>=0&&p.y<=H))}
export function drawStroke(ctx,s){if(!s.points.length)return;ctx.save();ctx.globalCompositeOperation=s.tool==='eraser'?'destination-out':'source-over';ctx.strokeStyle=s.color;ctx.fillStyle=s.color;ctx.lineCap='round';ctx.lineJoin='round';ctx.lineWidth=s.size*(s.tool==='eraser'?2:1);ctx.globalAlpha=s.tool==='soft'?.25:1;const path=()=>{ctx.beginPath();ctx.moveTo(s.points[0].x,s.points[0].y);for(const p of s.points.slice(1))ctx.lineTo(p.x,p.y);if(s.points.length===1){ctx.arc(s.points[0].x,s.points[0].y,ctx.lineWidth/2,0,Math.PI*2);ctx.fill()}else ctx.stroke()};if(s.tool==='crayon'){ctx.globalAlpha=.7;ctx.lineWidth=s.size*.72;path();ctx.globalAlpha=.25;ctx.lineWidth=s.size;ctx.setLineDash([2,4]);path()}else path();ctx.restore()}
